// npm i express express-session express-rate-limit bcrypt   (Express 5)
const express = require('express');
const session = require('express-session');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: 24 * 60 * 60 * 1000,
  },
}));

const users = new Map(); // username -> { passwordHash }; swap for your database

// Compared against when the username is unknown, so response time doesn't reveal which usernames exist.
const DUMMY_HASH = bcrypt.hashSync('dummy', 12);

// Only failed attempts (status >= 400) count toward the limit.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed login attempts. Try again later.' },
});

const credentials = (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Username and password are required.' });
  }
  next();
};

app.post('/register', credentials, async (req, res) => {
  const { username, password } = req.body;
  // bcrypt ignores everything past 72 bytes, so reject longer passwords instead of silently truncating.
  if (password.length < 8 || Buffer.byteLength(password) > 72) {
    return res.status(400).json({ error: 'Password must be 8 to 72 bytes long.' });
  }
  if (users.has(username)) return res.status(409).json({ error: 'Username is taken.' });
  users.set(username, { passwordHash: await bcrypt.hash(password, 12) });
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, credentials, async (req, res, next) => {
  const { username, password } = req.body;
  const user = users.get(username);
  const ok = await bcrypt.compare(password, user ? user.passwordHash : DUMMY_HASH);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid username or password.' });

  // A fresh session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.username = username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('connect.sid');
    res.json({ ok: true });
  });
});

const requireLogin = (req, res, next) =>
  req.session.username ? next() : res.status(401).json({ error: 'Not logged in.' });

app.get('/me', requireLogin, (req, res) => res.json({ username: req.session.username }));

app.listen(3000);
```

This has not been run. Three things are left out:

- **Persistent stores:** sessions, rate-limit counters and users all live in memory, so they are lost on restart and not shared across processes. Before production, give `session` and `rateLimit` a Redis store (`connect-redis`, `rate-limit-redis`) and move users to your database.
- **Per-username limiting:** the limiter counts per IP only, so an attacker rotating IPs against one account is not slowed. Add a second counter keyed on username if that matters to you.
- **Proxy setting:** behind a TLS-terminating reverse proxy, add `app.set('trust proxy', 1)`. Without it every client shares the proxy's IP for limiting and the secure cookie is never set. Do not set it when there is no proxy, because clients could then spoof their IP and dodge the limiter.
